// Statically homogeneous collection combinators generated by Ain.
fn ain_list_map<T, U, F: Fn(T) -> U>(values: Vec<T>, f: F) -> Vec<U> {
    values.into_iter().map(f).collect()
}
fn ain_list_filter<T: Clone, F: Fn(T) -> bool>(values: Vec<T>, f: F) -> Vec<T> {
    values.into_iter().filter(|item| f(item.clone())).collect()
}
fn ain_list_fold<T, A, F: Fn(A, T) -> A>(values: Vec<T>, seed: A, f: F) -> A {
    values.into_iter().fold(seed, f)
}
